1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Assigns a shared {@code householdId} when the request opts in with {@code sharesHousehold: true}.
10	 *
11	 * <p>The identifier is derived deterministically from the normalized last name and address (see
12	 * {@link OwnerIdentity#householdIdFor}), so it is stable: every owner living at the same address
13	 * under the same last name gets the same value regardless of creation order. The new owner and every
14	 * existing owner in that household are stamped with it, so both sides of an intentionally shared
15	 * household report the identifier. When {@code sharesHousehold} is not true no identifier is assigned,
16	 * and the owner's identity key (see {@link OwnerIdentity}) uses an empty household component.
17	 *
18	 * <p>Runs after {@link BuildOwner} (which publishes the new owner) and before {@link SaveOwner}.
19	 */
20	public class AssignHousehold {
21	
22	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
23	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        String householdId = OwnerIdentity.householdIdFor(owner.getLastName(), owner.getAddress());
27	        owner.setHouseholdId(householdId);
28	        // Stamp existing members of the same household so both sides share the identifier.
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (householdId.equals(OwnerIdentity.householdIdFor(existing.getLastName(), existing.getAddress()))
31	                    && !householdId.equals(existing.getHouseholdId())) {
32	                existing.setHouseholdId(householdId);
33	                ownerRepository.save(existing);
34	            }
35	        }
36	    }
37	}
