1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's {@code identityKey} — the single value all duplicate detection is expressed
12	 * through.
13	 *
14	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two owners
15	 * are duplicates only when their <em>whole</em> keys are equal (see {@link CheckIdentityUnique}).
16	 * Because the telephone is part of the key, two members of the same household (same
17	 * {@code householdId}) with different telephones have different keys and are both allowed.
18	 *
19	 * <p>The three components are normalized so the key is stable: the telephone to E.164 form (see
20	 * {@link TelephoneE164}), the email lower-cased and trimmed, and a null household rendered as empty.
21	 */
22	public final class OwnerIdentity {
23	
24	    private OwnerIdentity() {
25	    }
26	
27	    /** The identity key of a persisted owner, from its stored telephone, email and householdId. */
28	    public static String of(Owner owner) {
29	        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
30	    }
31	
32	    /** Assemble the identity key from the three components, normalizing telephone and email. */
33	    public static String key(String telephone, String email, String householdId) {
34	        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
35	                + (householdId == null ? "" : householdId);
36	    }
37	
38	    /**
39	     * The stable, shared household identifier for an owner's last name and address, normalizing both
40	     * the canonical way first (last name lower-cased with whitespace collapsed; address via
41	     * {@link AddressNormalizer}). Owners living at the same address under the same last name get the
42	     * same value regardless of creation order.
43	     */
44	    public static String householdIdFor(String lastName, String address) {
45	        return householdId(normalizeLastName(lastName), AddressNormalizer.normalize(address));
46	    }
47	
48	    /** First 16 upper-case hex chars of SHA-256(lastName|address), over already-normalized inputs. */
49	    private static String householdId(String lastName, String address) {
50	        return sha256Hex(lastName + "|" + address, 16);
51	    }
52	
53	    /**
54	     * The HASH8 half of an owner's region-and-hash {@code customerCode}: the first 8 upper-case hex
55	     * characters of SHA-256 over {@code normalizedTelephone + lastName}. The telephone is normalized
56	     * to E.164 form (null/invalid becomes empty) so the hash is stable across equivalent phone
57	     * formats; the last name is taken as stored.
58	     */
59	    public static String customerCodeHash(String telephone, String lastName) {
60	        return sha256Hex(normalizeTelephone(telephone) + (lastName == null ? "" : lastName), 8);
61	    }
62	
63	    /** First {@code length} upper-case hex chars of SHA-256 over the UTF-8 bytes of {@code input}. */
64	    private static String sha256Hex(String input, int length) {
65	        try {
66	            byte[] digest = MessageDigest.getInstance("SHA-256")
67	                    .digest(input.getBytes(StandardCharsets.UTF_8));
68	            StringBuilder sb = new StringBuilder(64);
69	            for (byte b : digest) {
70	                sb.append(String.format("%02x", b));
71	            }
72	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
73	        }
74	        catch (NoSuchAlgorithmException e) {
75	            throw new IllegalStateException("SHA-256 not available", e);
76	        }
77	    }
78	
79	    /** Telephone in E.164 form for comparison; null/invalid becomes empty. */
80	    private static String normalizeTelephone(String telephone) {
81	        String e164 = TelephoneE164.normalize(telephone);
82	        return e164 == null ? "" : e164;
83	    }
84	
85	    /** Email lower-cased and trimmed so comparison ignores case; null/blank becomes empty. */
86	    private static String normalizeEmail(String email) {
87	        if (email == null) {
88	            return "";
89	        }
90	        return email.trim().toLowerCase(Locale.ROOT);
91	    }
92	
93	    /** Last name lower-cased with runs of whitespace collapsed, so comparison ignores case/spacing. */
94	    private static String normalizeLastName(String value) {
95	        if (value == null) {
96	            return "";
97	        }
98	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
99	    }
100	}
