1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Rejects creating an owner whose {@code identityKey} exactly equals an existing owner's, so the
11	 * create endpoint responds 409 instead of storing a duplicate. This single check replaces the former
12	 * separate telephone, email and household checks: all duplicate detection is now expressed through
13	 * the one key {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
14	 * {@link OwnerIdentity}).
15	 *
16	 * <p>Only a whole-key match is a duplicate. Because the telephone is part of the key, two members of
17	 * the same household (same {@code householdId}) with different telephones have different keys and are
18	 * both allowed. The new owner's household component matches what {@link AssignHousehold} will assign:
19	 * a shared id when the request opts in with {@code sharesHousehold: true}, otherwise empty.
20	 *
21	 * <p>Runs after {@link ValidateOwner} (which normalizes and publishes the body) and before
22	 * {@link BuildOwner}, comparing against every existing owner's identity key.
23	 */
24	public class CheckIdentityUnique {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
29	                ? OwnerIdentity.householdIdFor(request.getLastName(), request.getAddress())
30	                : "";
31	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (identityKey.equals(OwnerIdentity.of(existing))) {
34	                throw new DuplicateIdentityException(identityKey);
35	            }
36	        }
37	    }
38	}
