1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Detects a <em>soft</em> duplicate: an existing owner that shares this owner's {@code lastName}
10	 * (compared case-insensitively) and {@code postcode} but has a <em>different</em> telephone.
11	 *
12	 * <p>Such an owner is deliberately still created — unlike a hard duplicate, whose whole identity key
13	 * matches an existing owner's and is rejected with 409 (see {@link CheckIdentityUnique}). Because the
14	 * telephone differs, the identity keys differ too, so a soft match is never also a hard duplicate.
15	 *
16	 * <p>The response surfaces the match through {@code possibleDuplicate} / {@code possibleDuplicateOf}.
17	 * The earliest (lowest id) matching owner is reported so the result is stable.
18	 */
19	public final class PossibleDuplicate {
20	
21	    private PossibleDuplicate() {
22	    }
23	
24	    /**
25	     * The id of an existing owner sharing {@code owner}'s last name and postcode but with a
26	     * different telephone, or {@code null} when there is no such match (including when the owner has
27	     * no postcode).
28	     */
29	    public static Integer matchFor(Owner owner, OwnerRepository ownerRepository) {
30	        String postcode = normalizePostcode(owner.getPostcode());
31	        if (postcode == null) {
32	            return null;
33	        }
34	        String lastName = normalizeLastName(owner.getLastName());
35	        String telephone = normalizeTelephone(owner.getTelephone());
36	        Integer match = null;
37	        for (Owner other : ownerRepository.findAll()) {
38	            if (other.getId() == null || other.getId().equals(owner.getId())) {
39	                continue;
40	            }
41	            if (!postcode.equals(normalizePostcode(other.getPostcode()))) {
42	                continue;
43	            }
44	            if (!lastName.equals(normalizeLastName(other.getLastName()))) {
45	                continue;
46	            }
47	            if (telephone.equals(normalizeTelephone(other.getTelephone()))) {
48	                continue; // same telephone is not a soft match (and would be a hard duplicate)
49	            }
50	            if (match == null || other.getId() < match) {
51	                match = other.getId();
52	            }
53	        }
54	        return match;
55	    }
56	
57	    private static String normalizePostcode(String postcode) {
58	        if (postcode == null) {
59	            return null;
60	        }
61	        String trimmed = postcode.trim();
62	        return trimmed.isEmpty() ? null : trimmed;
63	    }
64	
65	    private static String normalizeLastName(String value) {
66	        if (value == null) {
67	            return "";
68	        }
69	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
70	    }
71	
72	    private static String normalizeTelephone(String telephone) {
73	        String e164 = TelephoneE164.normalize(telephone);
74	        return e164 == null ? "" : e164;
75	    }
76	}
