1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's {@code membershipLevel} — the numeric rank (1 to 3) returned on the owner DTO
7	 * and recorded on the create audit line.
8	 *
9	 * <p>The level is fixed at creation from the owner's own fields:
10	 * <ul>
11	 *   <li>starts at {@code 1};</li>
12	 *   <li>adds {@code 1} when an email address is present (non-blank);</li>
13	 *   <li>adds {@code 1} when the owner's name is unique ({@code namesakeCount == 0});</li>
14	 *   <li>capped at {@code 3} — level 4 is reserved for tenure.</li>
15	 * </ul>
16	 */
17	public final class MembershipLevel {
18	
19	    private static final int MAX_LEVEL = 3;
20	
21	    private MembershipLevel() {
22	    }
23	
24	    /** The owner's membership level, from 1 to 3. */
25	    public static int of(Owner owner) {
26	        int level = 1;
27	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
28	            level++;
29	        }
30	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
31	            level++;
32	        }
33	        return Math.min(level, MAX_LEVEL);
34	    }
35	}
