27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 (a '+' then 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date", columnDefinition = "DATE")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date", columnDefinition = "DATE")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "membership_number")
73	    private String membershipNumber;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public String getPostcode() {
111	        return this.postcode;
112	    }
113	
114	    public void setPostcode(String postcode) {
115	        this.postcode = postcode;
116	    }
117	
118	    public LocalDate getRegistrationDate() {
119	        return this.registrationDate;
120	    }
121	
122	    public void setRegistrationDate(LocalDate registrationDate) {
123	        this.registrationDate = registrationDate;
124	    }
125	
126	    public LocalDate getBirthDate() {
127	        return this.birthDate;
128	    }
129	
130	    public void setBirthDate(LocalDate birthDate) {
131	        this.birthDate = birthDate;
132	    }
133	
134	    public String getCustomerCode() {
135	        return this.customerCode;
136	    }
137	
138	    public void setCustomerCode(String customerCode) {
139	        this.customerCode = customerCode;
140	    }
141	
142	    public String getHouseholdId() {
143	        return this.householdId;
144	    }
145	
146	    public void setHouseholdId(String householdId) {
147	        this.householdId = householdId;
148	    }
149	
150	    public Integer getNamesakeCount() {
151	        return this.namesakeCount;
152	    }
153	
154	    public void setNamesakeCount(Integer namesakeCount) {
155	        this.namesakeCount = namesakeCount;
156	    }
157	
158	    public String getMembershipNumber() {
159	        return this.membershipNumber;
160	    }
161	
162	    public void setMembershipNumber(String membershipNumber) {
163	        this.membershipNumber = membershipNumber;
164	    }
165	
166	    protected Set<Pet> getPetsInternal() {
167	        if (this.pets == null) {
168	            this.pets = new HashSet<>();
169	        }
170	        return this.pets;
171	    }
172	
173	    protected void setPetsInternal(Set<Pet> pets) {
174	        this.pets = pets;
175	    }
176	
177	    public List<Pet> getPets() {
178	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
179	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
180	        return Collections.unmodifiableList(sortedPets);
181	    }
182	
183	    public void setPets(List<Pet> pets) {
184	        this.pets = new HashSet<>(pets);
185	    }
186	
187	    public void addPet(Pet pet) {
188	        getPetsInternal().add(pet);
189	        pet.setOwner(this);
190	    }
191	
192	    /**
193	     * Return the Pet with the given name, or null if none found for this Owner.
194	     *
195	     * @param name to test
196	     * @return true if pet name is already in use
197	     */
198	    public Pet getPet(String name) {
199	        return getPet(name, false);
200	    }
201	
202	    /**
203	     * Return the Pet with the given name, or null if none found for this Owner.
204	     *
205	     * @param name to test
206	     * @return true if pet name is already in use
207	     */
208	    public Pet getPet(String name, boolean ignoreNew) {
209	        name = name.toLowerCase();
210	        for (Pet pet : getPetsInternal()) {
211	            if (!ignoreNew || !pet.isNew()) {
212	                String compName = pet.getName();
213	                compName = compName.toLowerCase();
214	                if (compName.equals(name)) {
215	                    return pet;
216	                }
217	            }
218	        }
219	        return null;
220	    }
221	
222	    public Pet getPet(Integer petId) {
223	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
224	    }
225	
226	    @Override
227	    public String toString() {
228	        return new ToStringCreator(this)
229	
230	            .append("id", this.getId())
231	            .append("new", this.isNew())
232	            .append("lastName", this.getLastName())
233	            .append("firstName", this.getFirstName())
234	            .append("address", this.address)
235	            .append("city", this.city)
236	            .append("telephone", this.telephone)
237	            .append("email", this.email)
238	            .toString();
239	    }
240	}
