package org.springframework.samples.petclinic.acceptance;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

class TempHouseholdTest extends AcceptanceBase {

    @Test
    void secondSameHouseholdRejectedUnlessSharesHousehold() throws Exception {
        String lastName = uniqueLastName();
        ObjectNode a = ownerNode();
        a.put("lastName", lastName);
        a.put("postcode", "2000");
        int idA = createOwnerOk(a);

        // Second owner, same lastName + postcode, no sharesHousehold -> 409.
        ObjectNode b = ownerNode();
        b.put("lastName", lastName);
        b.put("postcode", "2000");
        createOwner(b).andExpect(status().isConflict());

        // With sharesHousehold -> created, not flagged as possible duplicate.
        ObjectNode c = ownerNode();
        c.put("lastName", lastName);
        c.put("postcode", "2000");
        c.put("sharesHousehold", true);
        int idC = createOwnerOk(c);

        var cNode = fetchOwner(idC);
        assertEquals(fetchOwner(idA).get("householdId").asText(), cNode.get("householdId").asText());
        assertFalse(cNode.get("possibleDuplicate").asBoolean(), "declared member must not be flagged");
        // The earlier sole member also is not flagged.
        assertFalse(fetchOwner(idA).get("possibleDuplicate").asBoolean());
    }

    @Test
    void differentPostcodeSameLastNameIsNotHousehold() throws Exception {
        String lastName = uniqueLastName();
        ObjectNode a = ownerNode();
        a.put("lastName", lastName);
        a.put("postcode", "2000");
        createOwnerOk(a);
        ObjectNode b = ownerNode();
        b.put("lastName", lastName);
        b.put("postcode", "2001");
        int idB = createOwnerOk(b); // different postcode -> different household -> allowed
        assertFalse(fetchOwner(idB).get("possibleDuplicate").asBoolean());
    }
}

